        w, err := r.listerWatcher.Watch(resourceVersion)
        if err != nil {
            return err
        }

        err = r.watchHandler(w, stopCh)
        if err != nil {
            if apierrors.IsResourceExpired(err) {
                return nil // 触发重新List
            }
            return err
        }
    }
}

