// Redis 滑动窗口限流
func RateLimit(ctx context.Context, redis *redis.Client, key string, limit int, window time.Duration) (bool, error) {
    now := time.Now().UnixMilli()
    windowStart := now - window.Milliseconds()

    pipe := redis.Pipeline()
    // 移除窗口外的记录
    pipe.ZRemRangeByScore(ctx, key, "0", strconv.FormatInt(windowStart, 10))
    // 添加当前请求
    pipe.ZAdd(ctx, key, &redis.Z{Score: float64(now), Member: now})
    // 统计窗口内请求数
    count := pipe.ZCard(ctx, key)
    // 设置过期时间
    pipe.Expire(ctx, key, window)
    _, err := pipe.Exec(ctx)
    if err != nil {
        return false, err
    }

    return count.Val() <= int64(limit), nil
}

// 指数退避重试实现
type RetryConfig struct {
    MaxRetries      int
    BaseDelay       time.Duration
    MaxDelay        time.Duration
    BackoffFactor   float64
    JitterFraction  float64
    RetryableErrors []error
}

func RetryWithBackoff(ctx context.Context, config RetryConfig, fn func() error) error {
    var lastErr error
    for attempt := 0; attempt <= config.MaxRetries; attempt++ {
        err := fn()
        if err == nil {
            return nil
        }

        lastErr = err

        // 检查是否可重试
        if !isRetryable(err, config.RetryableErrors) {
            return err
        }

        // 检查上下文
        if ctx.Err() != nil {
            return ctx.Err()
        }

        // 计算退避时间
        delay := config.BaseDelay * time.Duration(math.Pow(config.BackoffFactor, float64(attempt)))
        if delay > config.MaxDelay {
            delay = config.MaxDelay
        }

        // 添加 Jitter
        jitter := time.Duration(float64(delay) * config.JitterFraction * (2*rand.Float64() - 1))
        delay += jitter

        select {
        case <-ctx.Done():
            return ctx.Err()
        case <-time.After(delay):
        }
    }
    return fmt.Errorf("max retries exceeded: %w", lastErr)
}

// 使用示例
config := RetryConfig{
    MaxRetries:     3,
    BaseDelay:      100 * time.Millisecond,
    MaxDelay:       5 * time.Second,
    BackoffFactor:  2.0,
    JitterFraction: 0.3,
}

err := RetryWithBackoff(ctx, config, func() error {
