.:53 {
    errors
    health {
       lameduck 5s
    }
    ready

    kubernetes cluster.local in-addr.arpa ip6.arpa {
       pods insecure
       fallthrough in-addr.arpa ip6.arpa
       ttl 30
    }

    # autopath 自动添加搜索域，减少客户端查询
    autopath @kubernetes

    prometheus :9153
    forward . /etc/resolv.conf {
       max_concurrent 1000
    }
    cache 30
    loop
    reload
    loadbalance
}

# 自定义 hosts 记录
