# 注释以 # 开头

# Server Block 基本格式
<zone>:[port] {
    <plugin> [arguments...]
    <plugin> {
        <option> <value>
    }
}

# 多Zone共享配置
<zone1> <zone2> <zone3>:[port] {
    <plugin>
}

# 1. 导入外部文件
import /etc/coredns/custom/*.conf

# 2. 环境变量替换
forward . {$UPSTREAM_DNS}

# 3. 多区域共享
cluster.local in-addr.arpa ip6.arpa:53 {
    kubernetes
}

# 4. 协议前缀
tls://.:853 {
    tls cert.pem key.pem ca.pem
    forward . 8.8.8.8
}

# 5. 通配符Zone
*.example.com:53 {
    forward . 10.0.0.1
}

# 多上游DNS服务器
forward . 8.8.8.8 8.8.4.4 1.1.1.1 {
    max_concurrent 1000
    max_fails 3
    health_check 5s
    policy round_robin
    expire 10s
}

# 基于域名分流
forward example.com 10.0.0.53 {
    max_concurrent 100
}

forward . /etc/resolv.conf {
    except example.com
    max_concurrent 1000
}

# 默认格式
log

# 自定义格式
log . "{remote}:{port} - [{time}] {>id} \"{type} {class} {name} {proto} {size}\" {rcode} {rsize} {duration}"

# 仅记录特定类型
log . {
    class denial    # 只记录否定响应
}

# 按域名过滤
log cluster.local {
    class all
}

.:53 {
    errors
    health

    # 重写ExternalName到实际CNAME
    rewrite continue {
        name regex (.*)\.external\.svc\.cluster\.local$ {1}.example.com
        answer name (.*)\.example\.com$ {1}.external.svc.cluster.local
    }

    kubernetes cluster.local in-addr.arpa ip6.arpa {
       pods insecure
       fallthrough in-addr.arpa ip6.arpa
    }

    forward . /etc/resolv.conf
    cache 30
    loop
    reload
    loadbalance
}

# DoT服务 (端口853)
tls://.:853 {
    tls /etc/coredns/cert.pem /etc/coredns/key.pem /etc/coredns/ca.pem

    errors
    health

    kubernetes cluster.local in-addr.arpa ip6.arpa {
       pods insecure
       fallthrough in-addr.arpa ip6.arpa
    }

    forward . tls://8.8.8.8 tls://8.8.4.4 {
        tls_servername dns.google
        health_check 5s
    }

    cache 30
    loop
    reload
    loadbalance
}

# 同时保留普通DNS (端口53)
.:53 {
    errors
    health

    kubernetes cluster.local in-addr.arpa ip6.arpa {
       pods insecure
       fallthrough in-addr.arpa ip6.arpa
    }

    forward . /etc/resolv.conf
    cache 30
    loop
    reload
    loadbalance
}

# 主集群配置
.:53 {
    errors
    health

    kubernetes cluster.local in-addr.arpa ip6.arpa {
       pods insecure
       fallthrough in-addr.arpa ip6.arpa
    }

    # 其他集群域名转发
    forward cluster-b.local 10.100.0.10 {
        max_concurrent 100
    }

    forward cluster-c.local 10.200.0.10 {
        max_concurrent 100
    }

    forward . /etc/resolv.conf
    cache 30
    loop
    reload
    loadbalance
}

.:53 {
    errors
    health

    # 对不存在的域名返回自定义响应
    template IN A blocked.domain.com {
        rcode NXDOMAIN
        authority "blocked.domain.com. 60 IN SOA ns.blocked.domain.com. admin.blocked.domain.com. 2021010100 3600 300 86400 60"
    }

    # 所有blocked子域返回0.0.0.0
    template IN A blocked {
        match .*\.blocked\.local$
        answer "{{ .Name }} 60 IN A 0.0.0.0"
        fallthrough
    }

    kubernetes cluster.local in-addr.arpa ip6.arpa {
       pods insecure
       fallthrough in-addr.arpa ip6.arpa
    }

    forward . /etc/resolv.conf
    cache 30
    loop
    reload
    loadbalance
}

wiki/05-网络/01-K8s网络核心/16-coredns-plugins:
file DBFILE [ZONES...] {
    transfer to ADDRESS...         # 允许区域传输的地址
    transfer from ADDRESS...       # 从主服务器拉取区域
    reload DURATION                # 重新加载间隔
    upstream [ADDRESS...]          # 上游解析器
}

example.com:53 {
    file /etc/coredns/db.example.com example.com {
        reload 10s
        transfer to *
    }
    errors
    log
}

auto [ZONES...] {
    directory DIR [REGEXP ORIGIN_TEMPLATE]
    reload DURATION
    no_reload
    upstream [ADDRESS...]
}

secondary [ZONES...] {
    transfer from ADDRESS
    transfer to ADDRESS
}

route53 [ZONE:HOSTED_ZONE_ID...] {
    credentials PROFILE [FILENAME]
    refresh DURATION
    fallthrough [ZONES...]
    upstream [ADDRESS...]
}

# 公共DNS (负载均衡)
forward . 8.8.8.8 8.8.4.4 1.1.1.1 {
    max_concurrent 1000
    policy round_robin
    health_check 5s
    max_fails 3
}

# DoT上游
forward . tls://8.8.8.8 tls://8.8.4.4 {
    tls_servername dns.google
    health_check 10s
}

# 内部DNS (顺序)
forward internal.company.com 10.0.0.53 10.0.0.54 {
    policy sequential
    max_fails 2
}

grpc FROM TO... {
    tls CERT KEY CA
    tls_servername NAME
    policy random|round_robin|sequential
}

alternate RCODE FROM TO... {
    same options as forward
}

# 当主DNS返回SERVFAIL或REFUSED时使用备用DNS
forward . 10.0.0.53 {
    max_concurrent 1000
}
alternate SERVFAIL,REFUSED . 8.8.8.8 8.8.4.4

# 1. 阻止域名 (返回0.0.0.0)
template IN A blocked.local {
    match .*\.blocked\.local$
    answer "{{ .Name }} 60 IN A 0.0.0.0"
}

# 2. 动态生成PTR记录
template IN PTR 10.in-addr.arpa {
    match ^(\d+)\.(\d+)\.(\d+)\.10\.in-addr\.arpa$
    answer "{{ .Name }} 60 IN PTR host-{{ .Group.3 }}-{{ .Group.2 }}-{{ .Group.1 }}.internal.local."
}

# 3. 返回NXDOMAIN
template ANY ANY forbidden.example.com {
    rcode NXDOMAIN
    authority "forbidden.example.com. 60 IN SOA ns.example.com. admin.example.com. 1 3600 300 86400 60"
}

header {
    response FIELD VALUE
    request FIELD VALUE
}

trace [ENDPOINT] {
    every FRACTION
    service NAME
    client_server
    datadog_analytics_rate RATE
}

trace zipkin:9411 {
    every 100        # 每100个请求采样1个
    service coredns
    client_server
}

acl [ZONES...] {
    allow|deny|block|filter net CIDR...
    allow|deny|block|filter net CIDR... {
        CLASS TYPE [CLASS TYPE...]
    }
}

acl {
    # 允许内部网络
    allow net 10.0.0.0/8
    allow net 172.16.0.0/12
    allow net 192.168.0.0/16

    # 允许Pod CIDR
    allow net 10.244.0.0/16

    # 拒绝其他
    block net *
}

# 按类型控制
acl cluster.local {
    allow net 10.0.0.0/8 {
        IN A
        IN AAAA
        IN SRV
    }
    deny net * {
        IN AXFR    # 禁止区域传输
        IN ANY     # 禁止ANY查询
    }
}

dnssec [ZONES...] {
    key file KEY...
    cache_capacity CAPACITY
}

dnstap ENDPOINT {
    identity IDENTITY
    version VERSION
    extra EXTRA
}

health :8080 {
    lameduck 5s    # 关闭前等待5秒
}

.:53 {
    # 1. 辅助插件 (最先)
    errors
    log
    debug              # 仅调试时

    # 2. 监控插件
    prometheus :9153

    # 3. 健康检查
    health {
        lameduck 5s
    }
    ready

    # 4. 安全插件
    acl {
        allow net 10.0.0.0/8
        block net *
    }

    # 5. 循环检测
    loop

    # 6. 修改插件 (在缓存之前)
    rewrite name suffix .old.local .new.local

    # 7. 缓存 (在数据源之前!)
    cache 30

    # 8. 数据源插件
    hosts /etc/coredns/hosts {
        fallthrough
    }

    kubernetes cluster.local in-addr.arpa ip6.arpa {
        pods insecure
        fallthrough in-addr.arpa ip6.arpa
    }

    # 9. 转发插件 (最后)
    forward . /etc/resolv.conf {
        max_concurrent 1000
    }

    # 10. 配置管理
    reload
    loadbalance
}

