        total.aborted  += percpu_stats[i].aborted;
        total.drop     += percpu_stats[i].drop;
        total.pass     += percpu_stats[i].pass;
        total.tx       += percpu_stats[i].tx;
        total.redirect += percpu_stats[i].redirect;
