    struct {
        __u64 pid;
        char data[64];
    } sample = {};

    sample.pid = bpf_get_current_pid_tgid() >> 32;

    bpf_perf_event_output(ctx, &dns_events,
                           BPF_F_CURRENT_CPU,
                           &sample, sizeof(sample));
    return 0;
}

