struct {
    __uint(type, BPF_MAP_TYPE_LPM_TRIE);
    __uint(max_entries, 65536);
    __type(key, struct ipv4_lpm_key);    /* key_size = 8 字节 */
    __type(value, struct acl_rule);
    __uint(map_flags, BPF_F_NO_PREALLOC);  /* LPM Trie 必须设置此标志 */
