}

# 追踪所有文件打开 (类似 opensnoop)
sudo bpftrace -e '
tracepoint:syscalls:sys_enter_openat 
{ printf("%s %s\n", comm, str(args->filename)); }'

# 统计文件读取延迟
sudo bpftrace -e '
kprobe:vfs_read { @start[tid] = nsecs; }
kretprobe:vfs_read / @start[tid] / {
    @us = hist((nsecs - @start[tid]) / 1000);
    delete(@start[tid]);
}'

# 追踪大文件读取 (> 1MB)
sudo bpftrace -e '
tracepoint:syscalls:sys_enter_read 
/ args->count > 1048576 / 
{ printf("LARGE READ: %s %d bytes\n", comm, args->count); }'

# 统计访问最多的目录
sudo bpftrace -e '
tracepoint:syscalls:sys_enter_openat
{ 
    $file = str(args->filename);
    if (strcontains($file, "/")) {
        @[comm] = count();
    }
}'

# 追踪文件删除
sudo bpftrace -e '
tracepoint:syscalls:sys_enter_unlinkat 
{ printf("%s deleted: %s\n", comm, str(args->pathname)); }'

# 追踪 TCP 连接建立
sudo bpftrace -e '
kprobe:tcp_connect 
{ 
    $sk = (struct sock *)arg0;
    printf("connect: %s -> %s:%d\n", 
           comm,
           ntop($sk->__sk_common.skc_daddr),
           $sk->__sk_common.skc_dport >> 8);
}'

# 统计 TCP 发送字节 (按进程)
sudo bpftrace -e '
kprobe:tcp_sendmsg 
{ @bytes[comm] = sum(arg2); }'

# 追踪 UDP 数据包
sudo bpftrace -e '
tracepoint:net:net_dev_xmit 
{ @pkts[comm] = count(); }'

# 追踪 DNS 查询 (UDP port 53)
