profile:hz:99 
{ @[kstack] = count(); }
interval:s:10 { exit(); }'

# 追踪上下文切换
sudo bpftrace -e '
tracepoint:sched:sched_switch 
{ @[args->prev_comm, args->next_comm] = count(); }'

# 统计进程调度延迟
sudo bpftrace -e '
tracepoint:sched:sched_wakeup 
{ @ts[args->pid] = nsecs; }
tracepoint:sched:sched_switch 
/ @ts[args->next_pid] / {
