// Ring Buffer Map（比 perf_event_array 更高效）
struct {
    __uint(type, BPF_MAP_TYPE_RINGBUF);
    __uint(max_entries, 1 << 20);   // 1MB 环形缓冲区
} ringbuf SEC(".maps");

struct network_event {
    __u64  timestamp_ns;
    __u32  src_ip;
    __u32  dst_ip;
    __u16  src_port;
    __u16  dst_port;
    __u8   proto;
    __u8   direction;  // 0=ingress, 1=egress
    __u16  pkt_len;
    __u32  cpu;
