package com.example.events;

import "google/protobuf/timestamp.proto";

message User {
  int64 id = 1;
  string name = 2;
  optional string email = 3;
  optional int32 age = 4;
  optional Address address = 5;
  repeated string tags = 6;
  google.protobuf.Timestamp created_at = 7;
  Status status = 8;

