deny[msg] {
  input.request.kind.kind == "Pod"
  image := input.request.object.spec.containers[_].image
  not image_signed(image)
  msg := sprintf("镜像未签名: %v", [image])
}

image_signed(image) {
  # 调用外部签名验证服务
  http.send({
    "method": "GET",
    "url": sprintf("https://notary.example.com/verify?image=%v", [image])
  }).status_code == 200
}

