apiVersion: v1
kind: ConfigMap
metadata:
  name: elasticsearch-alerts
  namespace: logging
data:
  alert-rules.json: |
    {
      "name": "企业级日志告警规则",
      "schedule": "0 */5 * * * ?",
      "inputs": [
        {
          "search": {
            "request": {
              "search_type": "query_then_fetch",
              "indices": ["filebeat-*"],
              "rest_total_hits_as_int": true,
              "body": {
                "size": 0,
                "query": {
                  "bool": {
                    "must": [
                      {
                        "range": {
                          "@timestamp": {
                            "gte": "now-5m",
                            "lt": "now"
                          }
                        }
                      }
                    ],
                    "should": [
                      {
                        "match": {
                          "log.level": "ERROR"
                        }
                      },
                      {
                        "match": {
                          "log.level": "FATAL"
                        }
                      }
                    ],
                    "minimum_should_match": 1
                  }
                },
                "aggs": {
                  "error_counts": {
                    "terms": {
                      "field": "kubernetes.container.name.keyword",
                      "size": 10
                    }
                  }
                }
              }
            }
          }
        }
      ],
      "triggers": [
        {
          "name": "高频错误日志告警",
          "severity": "high",
          "condition": {
            "script": {
              "source": "ctx.results[0].hits.total.value > params.threshold",
              "lang": "painless",
              "params": {
                "threshold": 100
              }
            }
          },
          "actions": [
            {
              "name": "发送告警通知",
              "destination_id": "slack_notifications",
              "message_template": {
                "source": "发现高频错误日志:\n- 时间范围: {{ctx.periodStart}} - {{ctx.periodEnd}}\n- 错误总数: {{ctx.results[0].hits.total.value}}\n- 详情请查看Kibana仪表板"
              },
              "throttle_enabled": true,
              "throttle": {
                "value": 10,
                "unit": "MINUTES"
              }
            }
          ]
        }
      ]
    }

