    if err != nil {
        panic(err)
    }

    // 配置QPS和Burst
    config.QPS = 100
    config.Burst = 200
    config.Timeout = 30 * time.Second

    // 创建clientset
    clientset, err := kubernetes.NewForConfig(config)
    if err != nil {
        panic(err)
    }

    // 列出default命名空间的Pods
