    corev1listers "k8s.io/client-go/listers/core/v1"
    "k8s.io/client-go/tools/cache"
    "k8s.io/client-go/util/workqueue"
    "k8s.io/klog/v2"
)

// Controller 控制器结构
type Controller struct {
    clientset     kubernetes.Interface
    podLister     corev1listers.PodLister
    podSynced     cache.InformerSynced
    workqueue     workqueue.RateLimitingInterface
}

// NewController 创建控制器
func NewController(
    clientset kubernetes.Interface,
    factory informers.SharedInformerFactory,
) *Controller {
    podInformer := factory.Core().V1().Pods()

    controller := &Controller{
        clientset: clientset,
        podLister: podInformer.Lister(),
        podSynced: podInformer.Informer().HasSynced,
        workqueue: workqueue.NewNamedRateLimitingQueue(
            workqueue.DefaultControllerRateLimiter(),
            "Pods",
        ),
    }

    // 添加事件处理器
    podInformer.Informer().AddEventHandler(cache.ResourceEventHandlerFuncs{
        AddFunc: controller.enqueuePod,
        UpdateFunc: func(old, new interface{}) {
            controller.enqueuePod(new)
        },
        DeleteFunc: controller.enqueuePod,
    })

    return controller
}

// enqueuePod 将Pod key加入队列
func (c *Controller) enqueuePod(obj interface{}) {
    var key string
    var err error
    if key, err = cache.MetaNamespaceKeyFunc(obj); err != nil {
        runtime.HandleError(err)
        return
    }
    c.workqueue.Add(key)
}

// Run 运行控制器
func (c *Controller) Run(workers int, stopCh <-chan struct{}) error {
    defer runtime.HandleCrash()
    defer c.workqueue.ShutDown()

    klog.Info("Starting controller")

    // 等待缓存同步
    klog.Info("Waiting for informer caches to sync")
    if ok := cache.WaitForCacheSync(stopCh, c.podSynced); !ok {
        return fmt.Errorf("failed to wait for caches to sync")
    }

    klog.Info("Starting workers")
    // 启动worker
    for i := 0; i < workers; i++ {
        go wait.Until(c.runWorker, time.Second, stopCh)
    }

    klog.Info("Controller started")
    <-stopCh
    klog.Info("Shutting down controller")
    return nil
}

// runWorker 工作循环
func (c *Controller) runWorker() {
    for c.processNextWorkItem() {
    }
}

// processNextWorkItem 处理队列中的下一个item
func (c *Controller) processNextWorkItem() bool {
    obj, shutdown := c.workqueue.Get()
    if shutdown {
        return false
    }

    err := func(obj interface{}) error {
        defer c.workqueue.Done(obj)

        key, ok := obj.(string)
        if !ok {
            c.workqueue.Forget(obj)
            return fmt.Errorf("expected string in workqueue but got %#v", obj)
        }

        // 执行reconcile逻辑
        if err := c.syncHandler(key); err != nil {
            // 重新入队
            c.workqueue.AddRateLimited(key)
            return fmt.Errorf("error syncing '%s': %s, requeuing", key, err.Error())
        }

        // 处理成功,清除重试计数
        c.workqueue.Forget(obj)
        klog.Infof("Successfully synced '%s'", key)
        return nil
    }(obj)

    if err != nil {
        runtime.HandleError(err)
        return true
    }

    return true
}

// syncHandler 实际的reconcile逻辑
func (c *Controller) syncHandler(key string) error {
    namespace, name, err := cache.SplitMetaNamespaceKey(key)
    if err != nil {
        return fmt.Errorf("invalid resource key: %s", key)
    }

    // 从缓存获取Pod
    pod, err := c.podLister.Pods(namespace).Get(name)
    if err != nil {
        // Pod已删除
        if errors.IsNotFound(err) {
            klog.Infof("Pod %s/%s has been deleted", namespace, name)
            return nil
        }
        return err
    }

    // 执行业务逻辑
    klog.Infof("Processing Pod %s/%s, Phase: %s", 
        pod.Namespace, pod.Name, pod.Status.Phase)

    // ... 实际业务逻辑

    return nil
}

func main() {
    config, _ := getKubeConfig()
    clientset, _ := kubernetes.NewForConfig(config)

    factory := informers.NewSharedInformerFactory(clientset, time.Hour)
    controller := NewController(clientset, factory)

    stopCh := make(chan struct{})
    factory.Start(stopCh)

    if err := controller.Run(2, stopCh); err != nil {
        klog.Fatalf("Error running controller: %s", err.Error())
    }
}

