# 🟡 中风险：会修改集群/资源状态，执行前请确认目标、影响范围与授权
# 快速进入 Pod Shell
ksh() {
  kubectl exec -it $1 -- /bin/bash
}

# 快速查看 Pod 日志
klog() {
  kubectl logs -f $1
}

# 快速删除 Evicted Pod
kdele() {
