func GetPodTemplateSpecHash(deployment *apps.Deployment) (string, error) {
    podTemplateSpecHasher := fnv.New32a()
    hash.DeepHashObject(podTemplateSpecHasher, deployment.Spec.Template)
    return fmt.Sprintf("%d", podTemplateSpecHasher.Sum32()), nil
}

func FindNewReplicaSet(deployment *apps.Deployment, rsList []*apps.ReplicaSet) *apps.ReplicaSet {
    newRSTemplate := GetModifiedReplicaSetTemplate(deployment)
    for _, rs := range rsList {
        if EqualIgnoreHash(&rs.Spec.Template, &newRSTemplate) {
            return rs
        }
    }
    return nil
}

// pkg/controller/deployment/sync.go
func (dc *DeploymentController) getNewReplicaSet(ctx context.Context, d *apps.Deployment, rsList []*apps.ReplicaSet, createIfNotExists bool) (*apps.ReplicaSet, error) {
    existingNewRS := FindNewReplicaSet(d, rsList)
    if existingNewRS != nil {
        return existingNewRS, nil
    }

    if !createIfNotExists {
        return nil, nil
    }

    podTemplateHash, err := GetPodTemplateSpecHash(d)
    if err != nil {
        return nil, err
    }

    newRSTemplate := *d.Spec.Template.DeepCopy()
    templateLabels := CloneAndAddLabel(d.Spec.Template.Labels, apps.DefaultDeploymentUniqueLabelKey, podTemplateHash)
    newRSTemplate.Labels = templateLabels

    newRS := &apps.ReplicaSet{
        ObjectMeta: metav1.ObjectMeta{
            Name:            d.Name + "-" + podTemplateHash,
            Namespace:       d.Namespace,
            Labels:          templateLabels,
            OwnerReferences: []metav1.OwnerReference{*metav1.NewControllerRef(d, controllerKind)},
            Annotations:     map[string]string{},
        },
        Spec: apps.ReplicaSetSpec{
            Replicas: new(int32),
            Selector: &metav1.LabelSelector{
                MatchLabels: templateLabels,
            },
            Template: newRSTemplate,
        },
    }

    *newRS.Spec.Replicas = 0

    SetNewReplicaSetAnnotations(d, newRS, *newRS.Spec.Replicas, true)
    deploymentutil.SetReplicasAnnotations(newRS, *(d.Spec.Replicas))

    newRS, err = dc.client.AppsV1().ReplicaSets(d.Namespace).Create(ctx, newRS, metav1.CreateOptions{})
    if err != nil {
        return nil, fmt.Errorf("error creating new replica set: %v", err)
    }

    dc.eventRecorder.Eventf(d, v1.EventTypeNormal, "NewReplicaSetCreated", "Created new replica set %q", newRS.Name)
    return newRS, nil
}

func (dc *DeploymentController) sync(ctx context.Context, deployment *apps.Deployment, rsList []*apps.ReplicaSet, podMap map[types.UID]*v1.PodList) error {
    newRS, allOldRSs, err := dc.getAllReplicaSetsAndSyncRevision(ctx, deployment, rsList, false)
    if err != nil {
        return err
    }

    if err := dc.scale(ctx, deployment, newRS, allOldRSs); err != nil {
        return err
    }

    _, err = dc.cleanupDeployment(ctx, allOldRSs, deployment)
    if err != nil {
        return err
    }

    return dc.syncRolloutStatus(ctx, allOldRSs, newRS, deployment)
}

func (dc *DeploymentController) cleanupDeployment(ctx context.Context, key string) error {
    namespace, name, err := cache.SplitMetaNamespaceKey(key)
    if err != nil {
        return err
    }

    klog.V(2).Infof("Cleaning up deployment %s/%s", namespace, name)

    selector, err := metav1.LabelSelectorAsSelector(nil)
    rsList, err := dc.rsLister.ReplicaSets(namespace).List(labels.Everything())
    if err != nil {
        return err
    }

    for _, rs := range rsList {
        if rs.DeletionTimestamp != nil {
            continue
        }
        if metav1.IsControlledBy(rs, &apps.Deployment{
            ObjectMeta: metav1.ObjectMeta{Name: name, Namespace: namespace},
        }) {
            if err := dc.client.AppsV1().ReplicaSets(namespace).Delete(ctx, rs.Name, metav1.DeleteOptions{}); err != nil {
                return err
            }
        }
    }

    return nil
}

// pkg/controller/replicaset/replica_set.go
func (rsc *ReplicaSetController) syncReplicaSet(ctx context.Context, key string) error {
    // 1. 解析 namespace/name
    namespace, name, err := cache.SplitMetaNamespaceKey(key)

    // 2. 获取 ReplicaSet
    rs, err := rsc.rsLister.ReplicaSets(namespace).Get(name)
    if err != nil {
        if errors.IsNotFound(err) {
            // ReplicaSet 已被删除，Pod 会被垃圾回收器清理
            return nil
        }
        return err
    }

    // 3. 获取该 RS 关联的所有 Pod
    podList, err := rsc.podLister.Pods(namespace).List(labels.SelectorFromSet(rs.Spec.Selector.MatchLabels))

    // 4. 过滤出真正属于该 RS 的 Pod（通过 OwnerReference 确认）
    filteredPods := controller.FilterActivePods(podList)

    // 5. 计算期望状态
    diff := *(rs.Spec.Replicas) - int32(len(filteredPods))

    // 6. 执行同步
    if diff > 0 {
        // 需要创建 diff 个 Pod
        return rsc.manageReplicas(ctx, rs, filteredPods, diff)
    } else if diff < 0 {
        // 需要删除 -diff 个 Pod
        return rsc.manageReplicas(ctx, rs, filteredPods, diff)
    }

    // 7. 更新 Status
    return rsc.updateReplicaSetStatus(ctx, rs, filteredPods)
}

// pkg/controller/replicaset/replica_set.go
func (rsc *ReplicaSetController) manageReplicas(ctx context.Context, rs *apps.ReplicaSet, pods []*v1.Pod, diff int32) error {
    if diff < 0 {
        // ===== 缩容：删除多余的 Pod =====
        // 计算需要删除的 Pod 数量
        diff *= -1

        // 优雅删除：考虑 PodDisruptionBudget
        // 先标记删除，等待 kubelet 终止容器
        errCh := make(chan error, diff)
        var wg sync.WaitGroup
        wg.Add(int(diff))

        for i := 0; i < int(diff); i++ {
            go func(pod *v1.Pod) {
                defer wg.Done()
                if err := rsc.podControl.DeletePod(ctx, rs.Namespace, pod.Name, rs); err != nil {
                    errCh <- err
                }
            }(pods[i])
        }
        wg.Wait()

    } else if diff > 0 {
        // ===== 扩容：创建缺失的 Pod =====
        // 使用限速器控制批量创建速度，避免 API Server 压力过大
        // 每次最多创建 500 个（BurstReplicas = 500）

        // 实际创建的 Pod 数受限于 Batch 大小
        batchSize := diff
        if batchSize > controller.BurstReplicas {
            batchSize = controller.BurstReplicas
        }

        errCh := make(chan error, batchSize)
        var wg sync.WaitGroup
        wg.Add(int(batchSize))

        for i := 0; i < int(batchSize); i++ {
            go func() {
                defer wg.Done()
                // 从 ReplicaSet 的 Template 创建 Pod
                if err := rsc.podControl.CreatePods(ctx, rs.Namespace, &rs.Spec.Template, rs, metav1.GetOptionsOf(rs)); err != nil {
                    errCh <- err
                }
            }()
        }
        wg.Wait()

        // 如果还有剩余未创建的，重新入队
        if diff > batchSize {
            // 将 RS 重新加入队列，触发下一轮创建
            rsc.enqueueRS(rs)
        }
    }

    return nil
}

// pkg/controller/controller_utils.go
var podCreationRateLimiter = workqueue.NewRateLimiter(
    workqueue.NewItemExponentialFailureRateLimiter(1*time.Millisecond, 1*time.Minute),
    100, // QPS
)

// 在 manageReplicas 中使用
if err := rsc.podControl.CreatePods(...); err != nil {
    // 如果创建失败，将 RS 重新入队等待重试
    rsc.enqueueRS(rs)
}

// 删除 Pod 前的 PDB 检查
func (r *RealPodControl) deletePod(namespace, name string, pod *v1.Pod) error {
    // 1. 获取 Pod 的 PDB
    pdbs, err := r.pdbLister.PodDisruptionBudgets(namespace).List(...)

    for _, pdb := range pdbs {
        if selector.Matches(labels.Set(pod.Labels)) {
            // 2. 检查 PDB 当前允许的 disruptions
            allowed := pdb.Status.DisruptionsAllowed
            if allowed == 0 {
                // 等待或跳过
                return fmt.Errorf("PodDisruptionBudget %s blocks deletion", pdb.Name)
            }
        }
    }

    // 3. 执行删除
    return r.KubeClient.CoreV1().Pods(namespace).Delete(ctx, name, ...)
}

// pkg/controller/replicaset/replica_set_utils.go
func (r RealPodControl) CreatePods(ctx context.Context, namespace string, template *v1.PodTemplateSpec, object runtime.Object) error {
    // 1. 从 Template 深拷贝创建 Pod 对象
    pod := &v1.Pod{
        ObjectMeta: metav1.ObjectMeta{
            Namespace:    namespace,
            GenerateName: template.GenerateName,  // 或使用 ControllerRef 生成名称
            Labels:       template.Labels,
            Annotations:  template.Annotations,
            OwnerReferences: []metav1.OwnerReference{
                // 设置 ReplicaSet 为 Pod 的 Owner
                *metav1.NewControllerRef(controllerObject, rsKind),
            },
        },
        Spec: template.Spec,
    }

    // 2. 通过 clientset 创建 Pod
    // 注意：此时 Pod 的 spec.nodeName 为空，需要等待调度器分配节点
    _, err := r.KubeClient.CoreV1().Pods(namespace).Create(ctx, pod, metav1.CreateOptions{})

    return err
}

// pkg/controller/replicaset/replica_set.go
func (rsc *ReplicaSetController) updateReplicaSetStatus(ctx context.Context, rs *apps.ReplicaSet, pods []*v1.Pod) error {
    // 1. 计算各类副本数
    replicas := int32(len(pods))
    fullyLabeledReplicas := 0
    readyReplicas := 0
    availableReplicas := 0

    for _, pod := range pods {
        // 检查 Pod 是否完全匹配 ReplicaSet 的标签
        if labels.Set(rs.Spec.Selector.MatchLabels).AsSelectorPreValidated().Matches(labels.Set(pod.Labels)) {
            fullyLabeledReplicas++
        }

        // 检查 Pod Ready
        if podutil.IsPodReady(pod) {
            readyReplicas++

            // 检查 Pod Available（Ready 超过 minReadySeconds）
            if podutil.IsPodAvailable(pod, rs.Spec.MinReadySeconds, metav1.Now()) {
                availableReplicas++
            }
        }
    }

    // 2. 构建新的 Status
    newStatus := apps.ReplicaSetStatus{
        Replicas:             replicas,
        FullyLabeledReplicas: int32(fullyLabeledReplicas),
        ReadyReplicas:        int32(readyReplicas),
        AvailableReplicas:    int32(availableReplicas),
        ObservedGeneration:   rs.Generation,
    }

    // 3. 如果 Status 有变化，更新 ReplicaSet
    if !reflect.DeepEqual(rs.Status, newStatus) {
        rs.Status = newStatus
        _, err := rsc.kubeClient.AppsV1().ReplicaSets(rs.Namespace).UpdateStatus(ctx, rs, metav1.UpdateOptions{})
        return err
    }

    return nil
}

// pkg/controller/deployment/rolling.go
func (dc *DeploymentController) rolloutRolling(ctx context.Context, d *apps.Deployment, rsList []*apps.ReplicaSet, podList []*v1.Pod) error {
    // 1. 获取当前活跃的 ReplicaSet（最新的）
    newRS, oldRSs, err := dc.getAllReplicaSetsAndSyncRevision(d, rsList, podList, true)

    // 2. 检查是否需要缩放所有 ReplicaSet（包括新旧）
    allRSs := append(oldRSs, newRS)
    scaled, err := dc.reconcileNewReplicaSet(ctx, allRSs, newRS, d)
    if scaled {
        // 已经执行了缩放操作，本轮同步完成
        return dc.syncRolloutStatus(ctx, allRSs, newRS, d)
    }

    // 3. 缩放旧的 ReplicaSet（逐步缩容）
    scaled, err = dc.reconcileOldReplicaSets(ctx, oldRSs, allRSs, d)
    if scaled {
        return dc.syncRolloutStatus(ctx, allRSs, newRS, d)
    }

    // 4. 清理完成历史版本的老 ReplicaSet
    if deploymentutil.DeploymentComplete(d, &d.Status) {
        dc.cleanupDeployment(oldRSs, d)
    }

    // 5. 同步 Deployment 状态
    return dc.syncRolloutStatus(ctx, allRSs, newRS, d)
}

// pkg/controller/deployment/rolling.go
func (dc *DeploymentController) reconcileNewReplicaSet(ctx context.Context, allRSs []*apps.ReplicaSet, newRS *apps.ReplicaSet, deployment *apps.Deployment) (bool, error) {
    // 1. 如果新 RS 已经满足期望副本数，无需操作
    if *(newRS.Spec.Replicas) == *(deployment.Spec.Replicas) {
        return false, nil
    }

    // 2. 计算新 RS 的目标副本数
    // 公式：newRSReplicas = deployment.Spec.Replicas + maxSurge - (allOldPods)
    // 简化为：newRSReplicas = min(deployment.Spec.Replicas + maxSurge, totalPods - minAvailable)

    newReplicasCount, err := deploymentutil.NewRSNewReplicas(deployment, allRSs, newRS)

    // 3. 更新新 RS 的副本数
    if *(newRS.Spec.Replicas) != newReplicasCount {
        newRS.Spec.Replicas = &newReplicasCount
        _, err := dc.client.AppsV1().ReplicaSets(newRS.Namespace).Update(ctx, newRS, metav1.UpdateOptions{})
        return true, err  // 返回 true 表示已执行缩放
    }

    return false, nil
}

// pkg/controller/deployment/util/deployment_util.go
func NewRSNewReplicas(deployment *apps.Deployment, allRSs []*apps.ReplicaSet, newRS *apps.ReplicaSet) (int32, error) {
    // 1. 计算 maxSurge 的绝对值
    maxSurge, err := intstrutil.GetValueFromIntOrPercent(
        intstrutil.ValueOrDefault(deployment.Spec.Strategy.RollingUpdate.MaxSurge, intstrutil.FromString("25%")),
        int(*(deployment.Spec.Replicas)),
        true, // isMaxSurge: 向上取整
    )

    // 2. 计算当前所有旧 RS 的 Pod 总数
    oldPodsCount := GetActualReplicaCountForReplicaSets(allRSs) - GetActualReplicaCountForReplicaSets([]*apps.ReplicaSet{newRS})

    // 3. 计算新 RS 的目标副本数
    // 目标：尽可能快地让新 RS 达到期望副本数，但不超过 maxSurge 限制
    newReplicasCount := *(deployment.Spec.Replicas)

    // 如果旧 RS 还有 Pod，新 RS 可能需要先创建更多副本
    // 具体计算考虑了比例缩放

    return newReplicasCount, nil
}

// pkg/controller/deployment/rolling.go
func (dc *DeploymentController) reconcileOldReplicaSets(ctx context.Context, oldRSs []*apps.ReplicaSet, allRSs []*apps.ReplicaSet, deployment *apps.Deployment) (bool, error) {
    // 1. 计算允许的最大不可用 Pod 数
    maxUnavailable, err := deploymentutil.MaxUnavailable(deployment)

    // 2. 计算当前不可用 Pod 数
    unavailablePods := deploymentutil.GetUnavailablePodsCount(allRSs, deployment)

    // 3. 计算可以缩容的旧 RS 数量
    // 原则：确保 unavailablePods <= maxUnavailable
    // 且 totalPods <= deployment.Replicas + maxSurge

    // 4. 按比例缩容旧 ReplicaSet
    // 如果有多个旧 RS（罕见），按比例分配缩容数量
    cleanupCount := len(oldRSs) - deploymentutil.MaxRevisionHistoryLimit(deployment)
    if cleanupCount > 0 {
        // 清理超出 revisionHistoryLimit 的老版本
        SortReplicaSetsByRevision(oldRSs)
        for i := 0; i < cleanupCount; i++ {
            dc.client.AppsV1().ReplicaSets(oldRSs[i].Namespace).Delete(ctx, oldRSs[i].Name, metav1.DeleteOptions{})
        }
    }

    // 5. 缩容仍然活跃的旧 RS
    scaledDown := false
    for _, rs := range oldRSs {
        if rs == nil {
            continue
        }

        // 计算该 RS 应缩容到的目标副本数
        targetScale := int32(0)  // 最终目标是 0

        // 比例缩放：如果新 RS 还没完全就绪，旧 RS 保留部分副本
        desiredReplicas := deploymentutil.GetProportion2(rs, deployment, *(deployment.Spec.Replicas), maxSurge)

        if desiredReplicas < *(rs.Spec.Replicas) {
            rs.Spec.Replicas = &desiredReplicas
            _, err := dc.client.AppsV1().ReplicaSets(rs.Namespace).Update(ctx, rs, metav1.UpdateOptions{})
            scaledDown = true
        }
    }

    return scaledDown, nil
}

// pkg/controller/deployment/proportion.go
func GetProportion(rs *apps.ReplicaSet, d *apps.Deployment) int32 {
    // 1. 获取该 RS 创建时的 Deployment Replicas
    // 从 annotation "deployment.kubernetes.io/revision" 和 RS 创建时的状态推算

    // 2. 计算比例
    // proportion = rs.Spec.Replicas * (d.Spec.Replicas / d.Status.Replicas)
    // 或基于 Deployment 更新时的期望状态

    // 简化逻辑：按比例分配当前期望副本数到各 RS
    if *(d.Spec.Replicas) == 0 {
        return 0
    }

    // 基于 RS 在创建时占 Deployment 副本的比例
    rsFraction := getReplicaSetFraction(rs, d)

    return integer.RoundToInt32(rsFraction * float64(*(d.Spec.Replicas)))
}

// pkg/controller/deployment/sync.go
if d.Spec.Paused {
    // 暂停时不执行 rolloutRolling 中的实际替换逻辑
    // 但会同步 ReplicaSet 的副本数到 Deployment.Spec.Replicas
    return dc.sync(ctx, d, podList, rsList, rsList)
}

