// pkg/controller/deployment/util/deployment_util.go
const (
    RevisionAnnotation        = "deployment.kubernetes.io/revision"
    DesiredReplicasAnnotation = "deployment.kubernetes.io/desired-replicas"
    MaxReplicasAnnotation     = "deployment.kubernetes.io/max-replicas"
)

func GetRevision(obj metav1.Object) int64 {
    v, ok := obj.GetAnnotations()[RevisionAnnotation]
    if !ok {
        return 0
    }
    revision, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0
    }
    return revision
}

func SetNewReplicaSetAnnotations(deployment *apps.Deployment, newRS *apps.ReplicaSet, newRevision int64) error {
    alreadySet := false
    if newRS.Annotations == nil {
        newRS.Annotations = make(map[string]string)
    } else {
        _, alreadySet = newRS.Annotations[RevisionAnnotation]
    }

    if !alreadySet {
        newRS.Annotations[RevisionAnnotation] = strconv.FormatInt(newRevision, 10)
    }

    newRS.Annotations[DesiredReplicasAnnotation] = strconv.Itoa(int(*deployment.Spec.Replicas))
    newRS.Annotations[MaxReplicasAnnotation] = strconv.Itoa(int(GetMaxReplicas(deployment)))

    return nil
}

// pkg/controller/deployment/rollback.go
func (dc *DeploymentController) rollbackToRevision(ctx context.Context, deployment *apps.Deployment, rsList []*apps.ReplicaSet, toRevision int64) (*apps.Deployment, error) {
    if toRevision == 0 {
        return deployment, nil
    }

    var targetRS *apps.ReplicaSet
    for _, rs := range rsList {
        if GetRevision(rs) == toRevision {
            targetRS = rs
            break
        }
    }

    if targetRS == nil {
        return nil, fmt.Errorf("unable to find specified revision %v in history", toRevision)
    }

    // 将目标 RS 的 PodTemplate 回写到 Deployment
    restoredDeployment := deployment.DeepCopy()
    restoredDeployment.Spec.Template = targetRS.Spec.Template

    // 计算回滚后的副本数
    if *targetRS.Spec.Replicas > 0 {
        *restoredDeployment.Spec.Replicas = *targetRS.Spec.Replicas
    }

    return dc.client.AppsV1().Deployments(restoredDeployment.Namespace).Update(ctx, restoredDeployment, metav1.UpdateOptions{})
}

// pkg/controller/deployment/sync.go
func (dc *DeploymentController) cleanupOldReplicaSets(ctx context.Context, oldRSs []*apps.ReplicaSet, deployment *apps.Deployment) ([]*apps.ReplicaSet, error) {
    revisionHistoryLimit := int32(10)
    if deployment.Spec.RevisionHistoryLimit != nil {
        revisionHistoryLimit = *deployment.Spec.RevisionHistoryLimit
    }

    if revisionHistoryLimit == 0 {
        for _, rs := range oldRSs {
            if err := dc.client.AppsV1().ReplicaSets(rs.Namespace).Delete(ctx, rs.Name, metav1.DeleteOptions{}); err != nil {
                return nil, err
            }
        }
        return nil, nil
    }

    SortReplicaSetsByRevision(oldRSs)

    i := 0
    for i < len(oldRSs)-int(revisionHistoryLimit) {
        if oldRSs[i].Status.Replicas != 0 || oldRSs[i].Spec.Replicas != nil && *oldRSs[i].Spec.Replicas != 0 {
            break
        }
        dc.client.AppsV1().ReplicaSets(oldRSs[i].Namespace).Delete(ctx, oldRSs[i].Name, metav1.DeleteOptions{})
        i++
    }

    return oldRSs[i:], nil
}

func (dc *DeploymentController) rolloutRecreate(
    ctx context.Context,
    d *apps.Deployment,
    rsList []*apps.ReplicaSet,
    podMap map[types.UID][]*v1.Pod,
) error

// pkg/controller/deployment/recreate.go
func (dc *DeploymentController) rolloutRecreate(
    ctx context.Context,
    d *apps.Deployment,
    rsList []*apps.ReplicaSet,
    podMap map[types.UID][]*v1.Pod,
) error {
    // Step 1: 获取新旧 ReplicaSet
    newRS, oldRSs, err := dc.getAllReplicaSetsAndSyncRevision(ctx, d, rsList, false)
    if err != nil {
        return err
    }
    allRSs := append(oldRSs, newRS)
    activeOldRSs := controller.FilterActiveReplicaSets(oldRSs)

    // Step 2: 缩容所有旧 ReplicaSet 到 0
    scaledDown, err := dc.scaleDownOldReplicaSetsForRecreate(ctx, activeOldRSs, d)
    if err != nil {
        return err
    }

    if scaledDown {
        // 触发了缩容，需要等待本次协调结束，下次协调再检查
        return dc.syncRolloutStatus(ctx, allRSs, newRS, d)
    }

    // Step 3: 检查旧 Pod 是否已全部终止
    if oldPodsRunning(newRS, oldRSs, podMap) {
        // 还有旧 Pod 在运行，继续等待
        return dc.syncRolloutStatus(ctx, allRSs, newRS, d)
    }

    // Step 4: 旧 Pod 已全清，创建新 ReplicaSet 并扩容到目标副本数
    if newRS == nil {
        newRS, oldRSs, err = dc.getAllReplicaSetsAndSyncRevision(ctx, d, rsList, true)
        if err != nil {
            return err
        }
        allRSs = append(oldRSs, newRS)
    }

    // Step 5: 扩容新 RS 到 Deployment.Spec.Replicas
    if _, err := dc.scaleUpNewReplicaSetForRecreate(ctx, newRS, d); err != nil {
        return err
    }

    // 清理超出 revisionHistoryLimit 的旧 RS
    if util.DeploymentComplete(d, &d.Status) {
        if err := dc.cleanupDeployment(ctx, oldRSs, d); err != nil {
            return err
        }
    }

    return dc.syncRolloutStatus(ctx, allRSs, newRS, d)
}

// scaleDownOldReplicaSetsForRecreate 将所有旧 RS 副本数设为 0
func (dc *DeploymentController) scaleDownOldReplicaSetsForRecreate(
    ctx context.Context,
    activeOldRSs []*apps.ReplicaSet,
    deployment *apps.Deployment,
) (bool, error) {
    scaled := false
    for i := range activeOldRSs {
        rs := activeOldRSs[i]
        // 如果 RS 已经是 0 副本，跳过
        if *(rs.Spec.Replicas) == 0 {
            continue
        }
        // 将 RS 的 Spec.Replicas 更新为 0
        scaledRS, updatedRS, err := dc.scaleReplicaSetAndRecordEvent(ctx, rs, 0, deployment)
        if err != nil {
            return false, err
        }
        if scaledRS {
            activeOldRSs[i] = updatedRS
            scaled = true
        }
    }
    return scaled, nil
}

// oldPodsRunning 检查是否还有旧 RS 的 Pod 在运行
func oldPodsRunning(newRS *apps.ReplicaSet, oldRSs []*apps.ReplicaSet, podMap map[types.UID][]*v1.Pod) bool {
    if oldPods := util.GetActualReplicaCountForReplicaSets(oldRSs); oldPods > 0 {
        return true
    }
    for _, pod := range podMap[newRS.UID] {
        switch pod.Status.Phase {
        case v1.PodFailed, v1.PodSucceeded:
            // 已终止的 Pod 不算活跃
        default:
            if pod.DeletionTimestamp != nil {
                // 处于 Terminating 状态，仍在运行
                return true
            }
        }
    }
    return false
}

// scaleUpNewReplicaSetForRecreate 将新 RS 副本数设置为期望值
func (dc *DeploymentController) scaleUpNewReplicaSetForRecreate(
    ctx context.Context,
    newRS *apps.ReplicaSet,
    deployment *apps.Deployment,
) (bool, error) {
    // 仅在新 RS 的当前副本数不等于期望副本数时才操作
    scaled, _, err := dc.scaleReplicaSetAndRecordEvent(
        ctx,
        newRS,
        *(deployment.Spec.Replicas),
        deployment,
    )
    return scaled, err
}

