func NewCertificateAuthority(config *certutil.Config) (*x509.Certificate, *rsa.PrivateKey, error) {
    key, err := NewPrivateKey()
    if err != nil {
        return nil, nil, err
    }
    cert, err := NewSelfSignedCACert(config, key)
    if err != nil {
