func newResetData(cmd *cobra.Command, opts *resetOptions, in io.Reader, out io.Writer, allowExperimental bool) (*resetData, error) {
    resetCfg, err := configutil.LoadOrDefaultResetConfiguration(
        opts.cfgPath,
