func Run(ctx context.Context, opts options.CompletedOptions) error {
    config, err := NewConfig(opts)          // Options → Config
    completed, err := config.Complete()     // 填充派生默认值
    server, err := CreateServerChain(completed)  // ★ 组装服务器链
