    'Authorization': `Bearer ${window.localStorage.getItem('authToken')}`,
    'Content-Type': 'application/json'
  };

  return cy.request({
    method: method,
    url: `${Cypress.env('apiBaseUrl')}${url}`,
    headers: { ...defaultHeaders, ...headers },
    body: body,
    failOnStatusCode: false
  });
});

