class KubectlQueryTool(BaseTool):
    name: str = "kubectl_query"
    description: str = (
        "查询 Kubernetes 集群资源状态。"
        "可以查看 Pod、Service、Deployment 等资源的详细信息。"
    )
    args_schema: Type[BaseModel] = KubectlQueryInput

    def _run(
        self,
        namespace: str = "default",
        resource: str = "pod",
        name: str = "",
    ) -> str:
