                retry_policy=RetryPolicy(maximum_attempts=2),
            )

            task_results.append({
                "task": task.description,
                "agent": agent_config.role,
                "result": result.output,
            })

            # CrewAI风格的上下文传递
            # 后续任务可以看到前面任务的结果

        return CrewResult(task_results=task_results)

