        message=Message(
            role="user",
            parts=[{"type": "text", "text": f"深度研究: {topic}"}],
        ),
    )

    # 3. 等待研究完成
    research_result = await research_agent.wait_for_completion(
        research_task.id,
    )

    # 4. 将研究结果发送给写作Agent
    writing_task = await writing_agent.create_task(
        message=Message(
            role="user",
            parts=[{
                "type": "text",
                "text": f"基于以下研究结果撰写报告:\n{research_result.artifacts[0].parts[0].text}",
