            "分析", "比较", "推理", "设计",
            "analyze", "compare", "reason", "design",
            "多步骤", "优化", "debug"
        ]

        query_lower = query.lower()

        # 简单模式匹配
        if len(query) < 20 and any(p in query_lower for p in simple_patterns):
