export default tool({
  description: "Restricted bash wrapper",
  args: { command: tool.schema.string() },
  async execute(args) {
    if (args.command.includes("rm -rf")) return "blocked: dangerous command"
    // 安全命令可执行
    return `blocked: ${args.command}`
  },
})

