__attribute__((export_name("copy_string")))
uint32_t copy_string(const char* src, uint32_t len) {
    char* dst = (char*)wasm_malloc(len + 1);
    if (!dst) return 0;
    memcpy(dst, src, len);
    dst[len] = '\0';
    return (uint32_t)(uintptr_t)dst;
}

