    b.RunParallel(func(pb *testing.PB) {
        for pb.Next() {
            fn.Call(ctx, 30)
        }
    })
}

// 对比：Native Go 函数
func fibonacci(n uint64) uint64 {
    if n <= 1 {
        return n
    }
    return fibonacci(n-1) + fibonacci(n-2)
}

func BenchmarkNativeFibonacci(b *testing.B) {
    b.RunParallel(func(pb *testing.PB) {
        for pb.Next() {
            fibonacci(30)
        }
    })
}

