async fn handle_request(req: Request<Body>) -> Result<Response<Body>, Infallible> {
    let path = req.uri().path().to_string();

    match path.as_str() {
        "/health" => Ok(Response::builder()
            .status(200)
            .body(Body::from(r#"{"status":"healthy"}"#))
