    healthz.InstallHandler(s.GenericAPIServer.Handler.NonGoRestfulMux,
        healthz.PingHealthz,
        healthz.LogHealthz,
        healthz.NewCacheSyncHealthz(s.informerFactory),
        healthz.NewInformerSyncHealthz(s.informerFactory),
    )
}

