import json
import os

def handle(event, context):
    """主处理函数"""
    body = event.body
    if isinstance(body, bytes):
        body = body.decode("utf-8")

    try:
        data = json.loads(body) if body else {}
    except json.JSONDecodeError:
        data = {"raw": body}

    # 业务逻辑
    result = {
        "message": "Processed",
        "input": data,
        "env": os.environ.get("ENVIRONMENT", "unknown")
    }

    return {
        "statusCode": 200,
        "body": json.dumps(result)
    }

