package main

import "fmt"

func main() {
    // 变量声明
    var name string = "John"
    var age int = 30
    var isActive bool = true

    // 类型推断
    var city = "New York"

    // 短声明 (仅在函数内)
    country := "USA"

    // 多变量声明
    var x, y, z int = 1, 2, 3
    a, b := 10, "hello"

    // 零值
    var i int       // 0
    var f float64   // 0.0
    var s string    // ""
    var ptr *int    // nil
    var arr [3]int  // [0 0 0]

    // 常量
    const PI = 3.14159
    const (
        StatusOK = 200
        StatusNotFound = 404
    )

    // iota (自增常量)
    const (
        Sunday = iota    // 0
        Monday           // 1
        Tuesday          // 2
        Wednesday        // 3
    )

    // 类型转换
    var a int = 10
    var b float64 = float64(a)
    var c string = fmt.Sprintf("%d", a)
}

// 基础类型
bool
string

// 整数类型
int  int8  int16  int32  int64    // 有符号
uint uint8 uint16 uint32 uint64   // 无符号
byte    // uint8 的别名
rune    // int32 的别名 (Unicode 码点)

// 浮点数
float32 float64

// 复数
complex64 complex128

// 指针
*T

// 数组 (固定长度)
[n]T

// 切片 (动态数组)
[]T

// 映射
map[K]V

// 通道
chan T

// 结构体
struct { ... }

// 接口
interface { ... }

// 函数
func(T1, T2) T3

// if-else
if x > 0 {
    fmt.Println("Positive")
} else if x < 0 {
    fmt.Println("Negative")
} else {
    fmt.Println("Zero")
}

// if 简短语句
if val, err := someFunc(); err != nil {
    fmt.Println("Error:", err)
} else {
    fmt.Println("Value:", val)
}

// switch
switch day := time.Now().Weekday(); day {
case time.Saturday, time.Sunday:
    fmt.Println("Weekend")
default:
    fmt.Println("Weekday")
}

// switch 无条件 (替代长 if-else)
score := 85
switch {
case score >= 90:
    fmt.Println("A")
case score >= 80:
    fmt.Println("B")
default:
    fmt.Println("C")
}

// for 循环 (唯一循环语句)
