nums := []int{1, 2, 3, 4, 5}
for i, v := range nums {
    fmt.Printf("Index: %d, Value: %d\n", i, v)
}

// 仅需值
for _, v := range nums {
    fmt.Println(v)
}

// 遍历 map
m := map[string]int{"a": 1, "b": 2}
for k, v := range m {
    fmt.Printf("%s: %d\n", k, v)
}

// 遍历字符串 (按 rune)
for i, r := range "Hello, 世界" {
    fmt.Printf("%d: %c\n", i, r)
}

// Go 1.21 及之前 (可能导致闭包问题)
for i := 0; i < 3; i++ {
    go func() {
        fmt.Println(i)  // 可能打印 3 3 3
    }()
}

// Go 1.22+ (每次迭代新变量)
for i := 0; i < 3; i++ {
