// Cond (条件变量)
var (
    cond   = sync.NewCond(&sync.Mutex{})
    ready  bool
)

func wait() {
    cond.L.Lock()
    for !ready {
        cond.Wait()
    }
    cond.L.Unlock()
}

func signal() {
    cond.L.Lock()
    ready = true
    cond.L.Unlock()
    cond.Broadcast()
}

