// panic (不可恢复错误)
func mustOpen(filename string) *os.File {
    f, err := os.Open(filename)
    if err != nil {
        panic(err)  // 抛出 panic
    }
    return f
}

// recover (恢复 panic)
func safeExecute(fn func()) {
    defer func() {
        if r := recover(); r != nil {
            fmt.Println("Recovered from panic:", r)
        }
    }()

    fn()
}

// 使用
safeExecute(func() {
    panic("something went wrong")
})
fmt.Println("Program continues")

