// 控制器核心逻辑伪代码
func (c *Controller) Reconcile(key string) error {
    // 1. 获取期望状态（从 API Server）
    desired := c.getDesiredState(key)
    // 2. 获取实际状态（从集群/外部系统）
    current := c.getCurrentState(key)
    // 3. 计算差异并执行协调
    if !reflect.DeepEqual(desired, current) {
        c.takeAction(desired, current)
    }
    return nil
}
// 触发条件：事件驱动（Watch）+ 定期重同步（resyncPeriod）

wiki/17-系统基础/06-知识字典/multi-cloud/multi-c:
# ========== Terraform多云基础设施定义 ==========
# main.tf - 多云基础设施主配置
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "~> 3.0"
    }
    google = {
      source  = "hashicorp/google"
      version = "~> 5.0"
    }
  }
}

# AWS基础设施
provider "aws" {
  region = var.aws_region
  alias  = "aws_primary"
}

provider "aws" {
  region = var.aws_backup_region
  alias  = "aws_backup"
}

# Azure基础设施
provider "azurerm" {
  features {}
  alias = "azure_primary"
}

# GCP基础设施
provider "google" {
  project = var.gcp_project
  region  = var.gcp_region
  alias   = "gcp_primary"
}

# ========== 多云Kubernetes集群定义 ==========
# aws_cluster.tf
resource "aws_eks_cluster" "primary" {
  provider = aws.aws_primary
  name     = "primary-cluster"
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids = aws_subnet.private[*].id
  }

  # 启用多云集成功能
  enabled_cluster_log_types = ["api", "audit", "authenticator", "controllerManager", "scheduler"]

  # 集群版本管理
  version = var.k8s_version
}

resource "aws_eks_node_group" "primary_workers" {
  provider = aws.aws_primary
  cluster_name    = aws_eks_cluster.primary.name
  node_group_name = "primary-workers"
  node_role_arn   = aws_iam_role.node.arn

  scaling_config {
    desired_size = 3
    max_size     = 10
    min_size     = 2
  }

  instance_types = ["m5.large", "m5.xlarge"]
  capacity_type  = "ON_DEMAND"

  # 多云标签标准化
  tags = {
    Environment    = "production"
    ClusterRole    = "primary"
    MultiCloudId   = var.multicloud_id
    CostCenter     = var.cost_center
  }
}

# azure_cluster.tf
resource "azurerm_kubernetes_cluster" "backup" {
  provider            = azurerm.azure_primary
  name                = "backup-cluster"
  location            = var.azure_location
  resource_group_name = azurerm_resource_group.backup.name
  dns_prefix          = "backup-cluster"

  default_node_pool {
    name       = "default"
    node_count = 3
    vm_size    = "Standard_D2_v2"
  }

  identity {
    type = "SystemAssigned"
  }

  # 网络配置
  network_profile {
    network_plugin = "azure"
    network_policy = "calico"
  }

  tags = {
    Environment  = "production"
    ClusterRole  = "backup"
    MultiCloudId = var.multicloud_id
    CostCenter   = var.cost_center
  }
}

# gcp_cluster.tf
resource "google_container_cluster" "disaster_recovery" {
  provider           = google.gcp_primary
  name               = "dr-cluster"
  location           = var.gcp_zone
  initial_node_count = 1

  # 私有集群配置
  private_cluster_config {
    enable_private_endpoint = true
    enable_private_nodes    = true
    master_ipv4_cidr_block  = "172.16.0.0/28"
  }

  # 安全配置
  master_auth {
    client_certificate_config {
      issue_client_certificate = false
    }
  }

  # 网络策略
  network_policy {
    enabled  = true
    provider = "CALICO"
  }

  tags = {
    Environment  = "disaster-recovery"
    ClusterRole  = "dr"
    MultiCloudId = var.multicloud_id
    CostCenter   = var.cost_center
  }
}

# ========== 多云网络互联配置 ==========
# network_connectivity.tf
resource "aws_dx_connection" "primary_dx" {
  provider      = aws.aws_primary
  name          = "primary-direct-connect"
  bandwidth     = "1Gbps"
  location      = var.dx_location
  tags = {
    Purpose = "multi-cloud-interconnect"
  }
}

resource "azurerm_express_route_circuit" "azure_er" {
  provider            = azurerm.azure_primary
  name                = "azure-express-route"
  resource_group_name = azurerm_resource_group.network.name
  location            = var.azure_location

  service_provider_name = "Equinix"
  peering_location      = var.er_peering_location
  bandwidth_in_mbps     = 1000

  sku {
    tier   = "Standard"
    family = "MeteredData"
  }

  tags = {
    Purpose = "multi-cloud-interconnect"
  }
}

# ========== 多云DNS配置 ==========
# dns_multicloud.tf
resource "aws_route53_zone" "multicloud_dns" {
  provider = aws.aws_primary
  name     = var.domain_name
}

resource "aws_route53_record" "primary_lb" {
  provider = aws.aws_primary
  zone_id  = aws_route53_zone.multicloud_dns.zone_id
  name     = "app.${var.domain_name}"
  type     = "A"

  alias {
    name                   = aws_lb.primary.dns_name
    zone_id                = aws_lb.primary.zone_id
    evaluate_target_health = true
  }
}

resource "azurerm_dns_a_record" "azure_lb" {
  provider            = azurerm.azure_primary
  name                = "app"
  zone_name           = var.domain_name
  resource_group_name = azurerm_resource_group.dns.name
  ttl                 = 300
  records             = [azurerm_public_ip.lb.ip_address]
}

# 全球负载均衡配置
resource "google_compute_global_forwarding_rule" "global_lb" {
  provider   = google.gcp_primary
  name       = "global-lb"
  target     = google_compute_target_http_proxy.default.id
  port_range = "80"

  # 基于延迟的智能路由
  load_balancing_scheme = "EXTERNAL"
}

# ========== Terraform多云K8s集群部署 ==========
# terraform.tf - 版本和Provider配置
terraform {
  required_version = ">= 1.5.0"

  # 远程状态存储(关键!避免状态冲突)
  backend "s3" {
    bucket         = "company-terraform-state"
    key            = "multicloud/clusters/terraform.tfstate"
    region         = "us-east-1"
    encrypt        = true
    dynamodb_table = "terraform-lock"
  }

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "~> 3.0"
    }
    google = {
      source  = "hashicorp/google"
      version = "~> 5.0"
    }
    kubernetes = {
      source  = "hashicorp/kubernetes"
      version = "~> 2.23"
    }
  }
}

# ========== variables.tf - 变量定义 ==========
variable "project_name" {
  description = "项目名称,用于资源命名"
  type        = string
  default     = "multicloud-prod"
}

variable "kubernetes_version" {
  description = "Kubernetes版本"
  type        = string
  default     = "1.28"
}

variable "node_count" {
  description = "每个集群的节点数"
  type        = number
  default     = 3
}

variable "tags" {
  description = "统一标签"
  type        = map(string)
  default = {
    Project     = "MultiCloud"
    Team        = "Platform"
    Environment = "Production"
    ManagedBy   = "Terraform"
  }
}

# ========== modules/aws-eks/main.tf - AWS EKS模块 ==========
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(var.tags, {
    Name = "${var.cluster_name}-vpc"
  })
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 4, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(var.tags, {
    Name                              = "${var.cluster_name}-private-${count.index + 1}"
    "kubernetes.io/role/internal-elb" = "1"
  })
}

resource "aws_eks_cluster" "main" {
  name     = var.cluster_name
  version  = var.kubernetes_version
  role_arn = aws_iam_role.cluster.arn

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    endpoint_private_access = true
    endpoint_public_access  = true
  }

  # 启用控制平面日志
  enabled_cluster_log_types = ["api", "audit", "authenticator"]

  tags = merge(var.tags, {
    Name = var.cluster_name
  })

  depends_on = [
    aws_iam_role_policy_attachment.cluster_policy
  ]
}

resource "aws_eks_node_group" "main" {
  cluster_name    = aws_eks_cluster.main.name
  node_group_name = "${var.cluster_name}-workers"
  node_role_arn   = aws_iam_role.node.arn
  subnet_ids      = aws_subnet.private[*].id

  scaling_config {
    desired_size = var.node_count
    max_size     = var.node_count * 2
    min_size     = 1
  }

  instance_types = ["t3.large"]
  capacity_type  = "SPOT"  # 使用Spot节省成本

  # 自动更新策略
  update_config {
    max_unavailable = 1
  }

  tags = merge(var.tags, {
    Name = "${var.cluster_name}-node-group"
  })
}

# ========== modules/azure-aks/main.tf - Azure AKS模块 ==========
resource "azurerm_resource_group" "main" {
  name     = "${var.cluster_name}-rg"
  location = var.location
  tags     = var.tags
}

resource "azurerm_virtual_network" "main" {
  name                = "${var.cluster_name}-vnet"
  address_space       = [var.vnet_cidr]
  location            = azurerm_resource_group.main.location
  resource_group_name = azurerm_resource_group.main.name
  tags                = var.tags
}

resource "azurerm_subnet" "aks" {
  name                 = "${var.cluster_name}-subnet"
  resource_group_name  = azurerm_resource_group.main.name
  virtual_network_name = azurerm_virtual_network.main.name
  address_prefixes     = [cidrsubnet(var.vnet_cidr, 4, 0)]
}

resource "azurerm_kubernetes_cluster" "main" {
  name                = var.cluster_name
  location            = azurerm_resource_group.main.location
  resource_group_name = azurerm_resource_group.main.name
  dns_prefix          = var.cluster_name
  kubernetes_version  = var.kubernetes_version

  default_node_pool {
    name       = "default"
    node_count = var.node_count
    vm_size    = "Standard_D2s_v3"
    vnet_subnet_id = azurerm_subnet.aks.id

    # 启用自动扩缩容
    enable_auto_scaling = true
    min_count           = 1
    max_count           = var.node_count * 2

    # 使用Spot实例
    priority        = "Spot"
    eviction_policy = "Delete"
    spot_max_price  = -1  # 使用当前Spot价格
  }

  identity {
    type = "SystemAssigned"
  }

  network_profile {
    network_plugin = "azure"
    network_policy = "calico"
  }

  tags = var.tags
}

# ========== modules/gcp-gke/main.tf - GCP GKE模块 ==========
resource "google_container_cluster" "main" {
  name               = var.cluster_name
  location           = var.zone
  min_master_version = var.kubernetes_version

  # 删除默认节点池,使用自定义节点池
  remove_default_node_pool = true
  initial_node_count       = 1

  # 启用工作负载身份
  workload_identity_config {
    workload_pool = "${var.project_id}.svc.id.goog"
  }

  # 网络配置
  network    = google_compute_network.vpc.name
  subnetwork = google_compute_subnetwork.subnet.name

  # 启用网络策略
  network_policy {
    enabled  = true
    provider = "CALICO"
  }

  # IP地址范围
  ip_allocation_policy {
    cluster_ipv4_cidr_block  = "/16"
    services_ipv4_cidr_block = "/22"
  }

  # 维护窗口
  maintenance_policy {
    daily_maintenance_window {
      start_time = "03:00"
    }
  }
}

resource "google_container_node_pool" "main" {
  name       = "${var.cluster_name}-pool"
  location   = var.zone
  cluster    = google_container_cluster.main.name
  node_count = var.node_count

  # 自动扩缩容
  autoscaling {
    min_node_count = 1
    max_node_count = var.node_count * 2
  }

  node_config {
    preemptible  = true  # 使用抢占式实例
    machine_type = "n2-standard-2"

    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform"
    ]

    labels = var.tags
  }
}

# ========== main.tf - 主配置文件 ==========
# AWS集群
module "aws_cluster" {
  source = "./modules/aws-eks"

  cluster_name       = "${var.project_name}-aws-us-east-1"
  vpc_cidr           = "10.0.0.0/16"
  kubernetes_version = var.kubernetes_version
  node_count         = var.node_count
  tags               = merge(var.tags, { Provider = "AWS" })
}

# Azure集群
module "azure_cluster" {
  source = "./modules/azure-aks"

  cluster_name       = "${var.project_name}-azure-westeurope"
  location           = "westeurope"
  vnet_cidr          = "10.1.0.0/16"
  kubernetes_version = var.kubernetes_version
  node_count         = var.node_count
  tags               = merge(var.tags, { Provider = "Azure" })
}

# GCP集群
module "gcp_cluster" {
  source = "./modules/gcp-gke"

  project_id         = var.gcp_project_id
  cluster_name       = "${var.project_name}-gcp-us-central1"
  zone               = "us-central1-a"
  kubernetes_version = var.kubernetes_version
  node_count         = var.node_count
  tags               = merge(var.tags, { Provider = "GCP" })
}

# ========== outputs.tf - 输出变量 ==========
output "aws_cluster_endpoint" {
  value       = module.aws_cluster.cluster_endpoint
  description = "AWS EKS集群API端点"
}

output "azure_cluster_fqdn" {
  value       = module.azure_cluster.cluster_fqdn
  description = "Azure AKS集群FQDN"
}

output "gcp_cluster_endpoint" {
  value       = module.gcp_cluster.cluster_endpoint
  description = "GCP GKE集群端点"
  sensitive   = true
}

# 生成kubeconfig
output "kubeconfig_commands" {
  value = <<-EOT
    # 配置AWS集群访问
    aws eks update-kubeconfig --name ${module.aws_cluster.cluster_name} --region us-east-1

    # 配置Azure集群访问
