done

# 生成使用趋势报告
echo "=== Resource Usage Trend Report ===" > $TEMP_DIR/report.txt
echo "Date	Pods	CPU(MilliCores)	Memory(Gi)	PVCs" >> $TEMP_DIR/report.txt

for i in $(seq 0 $DAYS); do
