          "auto_actions": ["Operator 重启后自动恢复"]
        },
        "version_notes": ""
      }
    },
    {
      "name": "F4. 网络分区", "action": "bottom_event", "step": "event_network_partition",
      "description": "Operator Pod 所在节点与 API Server 网络断开",
      "next_step": "end",
      "metadata": {
        "severity": "critical",
        "probability": "rare",
        "mttr_minutes": 15,
        "detection": {
          "events": ["NodeNotReady（Operator 所在节点）"],
