          { "if": { "source": "parallel_check_ca.stdout", "type": "regex", "pattern": "unknown authority|certificate chain" }, "then": { "action": "goto", "target": "evt_ca_chain_bad", "confidence": 0.9, "annotation": "CA 链问题" } }
