        ]
      },
      "match": {
        "rules": [
          { "if": { "source": "check_ca_logs.stdout", "type": "regex", "pattern": "unknown authority|unable to verify|certificate chain.*incomplete" }, "then": { "action": "confirm", "confidence": 0.9, "annotation": "CA 证书链问题" } }
