          { "if": { "source": "check_inconsistent_logs.stdout", "type": "numeric_compare", "operator": ">", "value": 3 }, "then": { "action": "confirm", "confidence": 0.75, "annotation": "多次间歇性连接问题，可能策略不一致" } }
