// k8s.io/kubernetes/pkg/controller/deployment/deployment_controller.go
// Deployment Controller 核心调谐
func (dc *DeploymentController) syncDeployment(ctx context.Context, key string) error {
    // 1. 获取 Deployment 和其所有 ReplicaSet
    deployment, err := dc.dLister.Deployments(ns).Get(name)
    allRSs := dc.getReplicaSetsForDeployment(deployment)

    // 2. 根据 strategy 执行不同逻辑
    switch deployment.Spec.Strategy.Type {
    case apps.RollingUpdateDeploymentStrategyType:
        // 滚动更新：按 maxSurge/maxUnavailable 控制节奏
        dc.rolloutRolling(ctx, deployment, allRSs)
    case apps.RecreateDeploymentStrategyType:
        // 重建：先缩容旧 RS 到 0，再扩容新 RS
        dc.rolloutRecreate(ctx, deployment, allRSs)
    }

    // 3. 清理旧 ReplicaSet（revisionHistoryLimit）
    dc.cleanupDeployment(ctx, allRSs, deployment)
}

// 滚动更新核心：按比例缩放新旧 RS
func (dc *DeploymentController) rolloutRolling(ctx context.Context, d *apps.Deployment, allRSs []*apps.ReplicaSet) {
    newRS, oldRSs := findNewAndOldRSs(d, allRSs)
    // maxSurge=25%: 新 RS 可超出期望副本数 25%
    // maxUnavailable=25%: 旧 RS 可低于期望副本数 25%
    scaledUp := dc.scaleUpNewReplicaSetForRollingUpdate(newRS, d)
    scaledDown := dc.scaleDownOldReplicaSetsForRollingUpdate(oldRSs, d)
}

wiki/22-概念/02-工作负载/deployments:
// k8s.io/kubernetes/pkg/controller/deployment/sync.go
func (dc *DeploymentController) syncDeployment(ctx context.Context, d *apps.Deployment) error {
    // 1. 获取所有关联的 ReplicaSet
    rsList := dc.getAllReplicaSets(d)
    // 2. 计算新 RS 的期望副本数
    newRS := dc.getNewReplicaSet(d, rsList)
    if d.Spec.Strategy.Type == apps.RollingUpdateDeploymentStrategyType {
        // 3. 滚动更新逻辑
        maxSurge := d.Spec.Strategy.RollingUpdate.MaxSurge       // 默认 25%
        maxUnavailable := d.Spec.Strategy.RollingUpdate.MaxUnavailable // 默认 25%
        // 4. 扩容新 RS（不超过 replicas + maxSurge）
        newReplicas := calculateNewReplicas(d, newRS, maxSurge)
        dc.scaleReplicaSet(newRS, newReplicas)
        // 5. 缩容旧 RS（不低于 replicas - maxUnavailable）
        for _, oldRS := range oldRSList {
            oldReplicas := calculateOldReplicas(d, oldRS, maxUnavailable)
            dc.scaleReplicaSet(oldRS, oldReplicas)
        }
    }
    // 6. 检查是否完成（新 RS 就绪 + 旧 RS 缩容到 0）
    if dc.deploymentComplete(d, newRS) {
        // 清理旧 RS（保留 revisionHistoryLimit 个）
        dc.cleanupOldReplicaSets(rsList, d.Spec.RevisionHistoryLimit)
    }
    return nil
}

