    // 3. 计算期望副本数（取所有指标的最大值）
    desiredReplicas := max(allMetricReplicas)
    // 公式: ceil(currentReplicas * currentMetric / targetMetric)

    // 4. 应用 behavior 约束（稳定窗口 + 速率限制）
